'use strict';
// Only in-memory state. No fetch, storage, Woo scripts or submissions.
const variants={A:['Refinamiento recomendado','Banner completo · 3 columnas · controles alineados.'],B:['Catálogo compacto','Banner más breve · productos en filas · menor densidad vertical.'],C:['Catálogo protagonista','Catálogo primero en móvil · banner lateral y 2 columnas en desktop.']};
let variant='A',selection=new Map(),feedbackTimer;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function setVariant(key){variant=variants[key]?key:'A';document.body.dataset.variant=variant;const url=new URL(location.href);url.searchParams.set('variant',variant);history.replaceState(null,'',url);$('#variant-label').textContent=`PROTOTIPO · ${variant} · ${variants[variant][0]}`;$('#variant-summary').textContent=variants[variant][1];$$('[data-variant]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',b.dataset.variant===variant)});}
function cycle(n){setVariant(['A','B','C'][(['A','B','C'].indexOf(variant)+n+3)%3]);}
setVariant(new URLSearchParams(location.search).get('variant'));
$('#variant-prev').onclick=()=>cycle(-1);$('#variant-next').onclick=()=>cycle(1);$$('button[data-variant]').forEach(b=>b.onclick=()=>setVariant(b.dataset.variant));
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"]')||$('dialog[open]')||e.altKey||e.ctrlKey||e.metaKey)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();cycle(e.key==='ArrowLeft'?-1:1)}});
function feedback(text){$('#proto-feedback').textContent=text;clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>$('#proto-feedback').textContent='',5000)}
function renderSelection(){const list=$('#selection-items');list.replaceChildren();selection.forEach((item,id)=>{const li=document.createElement('li');li.textContent=`${item.name} · ${item.qty} unidades (simulación)`;const b=document.createElement('button');b.textContent='Quitar';b.onclick=()=>{selection.delete(id);renderSelection()};li.append(b);list.append(li)});$('#selection-empty').hidden=selection.size>0;$$('.fpw-basket-count').forEach(el=>el.textContent=selection.size);$$('.product-card').forEach((card,id)=>{const b=card.querySelector('.proto-add');b.classList.toggle('is-added',selection.has(id));b.textContent=selection.has(id)?'Actualizar selección':'Agregar a Cotización';let status=card.querySelector('.proto-card-status');if(!status){status=document.createElement('p');status.className='proto-card-status';card.append(status)}status.textContent=selection.has(id)?`${selection.get(id).qty} unidades agregadas · Simulación`:'';});}
$$('.product-card').forEach((card,id)=>{const input=card.querySelector('input.qty');const normalize=()=>{input.value=Math.max(Number(input.min),Math.floor(Number(input.value)||Number(input.min)));return Number(input.value)};card.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{input.value=normalize()+Number(b.dataset.step)*(Number(input.step)||1);normalize()});input.addEventListener('change',normalize);card.querySelector('.proto-add').onclick=()=>{const qty=normalize(),name=card.querySelector('.woocommerce-loop-product__title').textContent.trim();selection.set(id,{name,qty});renderSelection();feedback(`${qty} unidades de ${name} agregadas solo a esta simulación.`)};});
$$('[data-fp-dialog]').forEach(b=>b.onclick=()=>{$$('dialog[open]').forEach(d=>d.close());$('#'+b.dataset.fpDialog).showModal();b.setAttribute('aria-expanded','true')});$$('dialog').forEach(d=>{d.querySelectorAll('[data-fp-close]').forEach(b=>b.onclick=()=>d.close());d.addEventListener('close',()=>$$('[data-fp-dialog]').forEach(b=>b.setAttribute('aria-expanded','false')))});
$$('a').forEach(a=>a.addEventListener('click',e=>{if(a.dataset.simulation){e.preventDefault();feedback('Prototipo: este enlace no abre comunicaciones ni páginas externas. Los datos de contacto se conservan en el pie.');return;}if(a.dataset.detail){e.preventDefault();feedback('Prototipo: la ficha completa queda fuera de esta comparación. Puedes evaluar cantidades y selección aquí.');return;}const href=a.getAttribute('href');if(href==='#catalogo'){const category=a.dataset.category;$$('.product-card').forEach(card=>card.hidden=!!category&&card.querySelector('.product-category').textContent.trim()!==category);$('#filter-state').hidden=!category;$('#filter-state').textContent=category?`Categoría: ${category}. Muestra limitada a los ocho destacados. Usa «Ver todo» en el menú para restablecer.`:'';}$$('dialog[open]').forEach(d=>d.close());}));
$('#simulate-send').onclick=()=>{$('#selection-feedback').textContent=selection.size?'Simulación completada. No se enviaron datos ni se creó una solicitud real.':'Selecciona al menos un producto para evaluar esta simulación.'};
$('#clear-selection').onclick=()=>{selection.clear();renderSelection();$('#selection-feedback').textContent='Selección de prueba vaciada.'};
document.addEventListener('submit',e=>e.preventDefault());
renderSelection();
